// Renders the collected statistics as a TypeScript module: JSON with bare
// keys and single quotes, frozen with `as const` so the page keeps literal
// types (the half-day keys drive BuildHalfDayKey).
export function renderBuildStats(stats) {
  const header = `// Generated by scripts/build/collectBuildStats.mjs from the git history of
// this repository. Do not edit by hand: run
// \`node scripts/build/collectBuildStats.mjs\` after new commits and commit the
// result. The page at /built imports this file and never reads git at runtime.
`
  const body = JSON.stringify(stats, null, 2)
    .replaceAll(/"(\w+)":/g, '$1:')
    .replaceAll(
      /"((?:[^"\\]|\\.)*)"/g,
      (_match, text) => `'${text.replaceAll("'", "\\'")}'`,
    )
  return `${header}export const buildStats = ${body} as const\n`
}
